package com.nexamart.backend.domain;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="products") public class Product{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String name;@Column(length=2000)private String description;@ManyToOne(optional=false)private Category category;@Column(nullable=false,precision=19,scale=2)private BigDecimal price;private BigDecimal discount=BigDecimal.ZERO;private String sku;private String unit;private Integer stock=0;private boolean available=true;private String imageUrl;private Instant createdAt=Instant.now();private Instant updatedAt=Instant.now();public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public Category getCategory(){return category;}public void setCategory(Category v){category=v;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal v){price=v;}public BigDecimal getDiscount(){return discount;}public void setDiscount(BigDecimal v){discount=v;}public String getSku(){return sku;}public void setSku(String v){sku=v;}public String getUnit(){return unit;}public void setUnit(String v){unit=v;}public Integer getStock(){return stock;}public void setStock(Integer v){stock=v;}public boolean isAvailable(){return available;}public void setAvailable(boolean v){available=v;}public String getImageUrl(){return imageUrl;}public void setImageUrl(String v){imageUrl=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void touch(){updatedAt=Instant.now();}}
